int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    char **codes = (char **)malloc(sizeof(char*) * n);
    if (!codes) return 0;

    char buf[MAXL];
    int impossible = 0;
    int maxlen = 0;

    for (int i = 0; i < n; i++) {
        if (scanf("%s", buf) != 1) return 0;
        int len = (int)strlen(buf);

        char *t = (char *)malloc((len + 2) * sizeof(char));
        if (!t) return 0;

        int m = 0;
        t[m++] = buf[0];
        for (int j = 0; j + 1 < len; j++) {
            if (is_vowel(buf[j])) t[m++] = buf[j + 1];
        }
        t[m] = '\0';
        codes[i] = t;
        if (m > maxlen) maxlen = m;
    }

    qsort(codes, n, sizeof(char*), cmp_str);

    for (int i = 1; i < n; i++) {
        if (strcmp(codes[i-1], codes[i]) == 0) {
            impossible = 1;
            break;
        }
    }

    if (impossible) {
        printf("-1\n");
        for (int i = 0; i < n; i++) free(codes[i]);
        free(codes);
        return 0;
    }

    int answer = 1;
    for (int i = 1; i < n; i++) {
        const char *a = codes[i-1];
        const char *b = codes[i];
        int lcp = 0;
        while (a[lcp] && b[lcp] && a[lcp] == b[lcp]) lcp++;
        int need = lcp + 1;
        if (need > answer) answer = need;
    }

    if (answer > maxlen) answer = maxlen;
    printf("%d\n", answer);

    for (int i = 0; i < n; i++) free(codes[i]);
    free(codes);
    return 0;
}

