public class Main {
    static boolean isVowel(char c) {
        return c == 'a' || c == 'i' || c == 'u' || c == 'e' || c == 'o';
    }

    static String baseString(String name) {
        StringBuilder sb = new StringBuilder();
        sb.append(name.charAt(0));
        for (int i = 0; i < name.length() - 1; i++) {
            if (isVowel(name.charAt(i))) {
                sb.append(name.charAt(i + 1));
            }
        }
        return sb.toString();
    }

    static boolean allDistinct(String[] bases, int k) {
        Set<String> set = new HashSet<>();
        for (String b : bases) {
            String code = b.substring(0, Math.min(k, b.length()));
            if (!set.add(code)) return false;
        }
        return true;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String[] names = new String[n];
        for (int i = 0; i < n; i++) names[i] = sc.next();

        String[] bases = new String[n];
        int maxLen = 0;
        for (int i = 0; i < n; i++) {
            bases[i] = baseString(names[i]);
            maxLen = Math.max(maxLen, bases[i].length());
        }

        if (!allDistinct(bases, maxLen)) {
            System.out.println("impossible");
            return;
        }

        int lo = 1, hi = maxLen, ans = maxLen;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (allDistinct(bases, mid)) { ans = mid; hi = mid - 1; }
            else lo = mid + 1;
        }
        System.out.println(ans);
    }
}

