public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c != -1 && c <= ' ');
            if (c == -1) return null;
            while (c != -1 && c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        Integer nextInt() throws IOException {
            String s = next();
            if (s == null) return null;
            return Integer.parseInt(s);
        }
    }

    static boolean isVowel(char c) {
        return c == 'a' || c == 'i' || c == 'u' || c == 'e' || c == 'o';
    }

    static String baseCode(String s) {
        StringBuilder sb = new StringBuilder();
        sb.append(s.charAt(0));
        for (int i = 0; i + 1 < s.length(); i++) {
            if (isVowel(s.charAt(i))) {
                sb.append(s.charAt(i + 1));
            }
        }
        return sb.toString();
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        Integer nObj = fs.nextInt();
        if (nObj == null) return;
        int n = nObj;

        String[] codes = new String[n];
        int maxLen = 0;

        for (int i = 0; i < n; i++) {
            String name = fs.next();
            codes[i] = baseCode(name);
            maxLen = Math.max(maxLen, codes[i].length());
        }

        // If two airports have identical full generated strings, they can never be distinguished.
        HashSet<String> fullSet = new HashSet<>();
        for (String c : codes) {
            if (!fullSet.add(c)) {
                System.out.println(-1);
                return;
            }
        }

        // Find minimum k such that all prefixes of length min(k, code.length()) are distinct.
        for (int k = 1; k <= maxLen; k++) {
            HashSet<String> seen = new HashSet<>();
            boolean ok = true;
            for (String c : codes) {
                String t = c.length() <= k ? c : c.substring(0, k);
                if (!seen.add(t)) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                System.out.println(k);
                return;
            }
        }

        // Since all full strings are distinct, k = maxLen must work, but keep fallback.
        System.out.println(-1);
    }
}

